jQuery(function($){console.log("✅ Popup (reload version, centered) initialized");$(".open-popup").on("click",function(){const product=$(this).data("product")||"your product";console.log("🧩 Popup requested for:",product);$(".popup-content h2").html("Enquire about<br/>our "+product);$("#input_2_4").val(product);$(".custom-popup").css({display:"flex",opacity:0}).addClass("active").animate({opacity:1},200);$("body").addClass("no-scroll")});$(".close-popup, .custom-popup").on("click",function(e){if($(e.target).is(".custom-popup, .close-popup")){$(".custom-popup").animate({opacity:0},200,function(){$(this).removeClass("active").css("display","none")});$("body").removeClass("no-scroll");console.log("❎ Popup closed")}});$(document).on("gform_confirmation_loaded",function(event,formId){if(formId===2){console.log("✅ Form submitted successfully, reloading...");setTimeout(()=>{location.reload()},1200)}})})